/* eslint-disable no-nested-ternary */
/* eslint-disable react/destructuring-assignment */
import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Form, Button, Input, message } from 'antd';
import { EyeOutlined, EyeInvisibleOutlined } from '@ant-design/icons';
import { useDispatch, useSelector } from 'react-redux';
import { useQueryClient, useMutation } from 'react-query';

import {
  handleUpdateMFAStatus,
  useFetchMFAStatus,
} from 'components/features/setting/useSettingPage';
import { getUser } from 'redux/actions/profile';

// styled components
import { StyledButton, StyledDisableModal, StyledEnableModal, StyledFigure, StyledMFAButton, FormItemStyled, FormContainer } from './styles';

const FormItem = Form.Item;

const MultiFactorAuthentication = () => {
  const formRef = useRef();
  const queryClient = useQueryClient();

  const [visibleMfa, setVisibleMfa] = useState(false);
  const [continueDisableMfa, setContinueDisableMfa] = useState(false);
  const [isMfaEnabled, setIsMfaEnabled] = useState();
  const [visibleDisableMFAModal, setVisibleDisableMFAModal] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const dispatch = useDispatch();
  const {
    profileReducer: user,
    currentOrgReducer: { orgId },
  } = useSelector((state) => state);

  const teamQueryKey = `teamList${orgId}`;
  const hasMfaEnabled = useMemo(() => user?.mfaEnabled, [user?.mfaEnabled]);

  const disableMFA = () => {
    setVisibleDisableMFAModal(true);
  };

  const toggleMfa = (flag) => {
    setIsMfaEnabled(flag);
  };

  const flagChange = (flag) => {
    setVisibleMfa(flag);
  };

  const handleMFAModalClose = () => {
    isMfaEnabled ? setVisibleDisableMFAModal(false) : flagChange(false);
  };

  const { refetch: fetchMFAStatus, isFetching: loading,  data : mfaData } = useFetchMFAStatus();
  const { mutate: mutateMFAStatus, isLoading } = useMutation(
    handleUpdateMFAStatus,
    {
      onSuccess: (response) => {
        toggleMfa(!hasMfaEnabled);
        setContinueDisableMfa(false);
        handleMFAModalClose();
        queryClient.setQueryData(teamQueryKey, (oldData) => {
          const newData =
            oldData?.length &&
            oldData.map((team) => {
              if (team?.email === user?.email) {
                return { ...team, mfaEnabled: !hasMfaEnabled };
              }
              return team;
            });

          return newData;
        });
        message.success(response?.data?.message);
        dispatch(getUser());
      },
      onError: (error) => {
        const response = error?.response?.data;
        if (response?.error) {
          formRef.current.setFields([
            {
              name: 'password',
              status: 'error',
              errors: [response?.error?.message ?? response?.error['code1'][0] ?? response?.error['code2'][0]],
            }
          ])
        }
      },
    }
  );

  const showMfaModal = () => {
    fetchMFAStatus();
  };

  const handleModalDisplay = () => {
    isMfaEnabled ? disableMFA() : showMfaModal()
  }

  const handleSubmit = () => {
    formRef.current.validateFields().then((values) => {
      mutateMFAStatus(values);
    });
  };

  const handlePasswordVerification = () => {
    formRef.current.validateFields().then((values) => {
      mutateMFAStatus({
        otp: values.password,
      }, 'disable-mfa');
    })
  }

  useEffect(() => {
    toggleMfa(hasMfaEnabled);
  }, [hasMfaEnabled]);

  useEffect(()=>{
    mfaData?.secret && flagChange(true);
    !loading && mfaData?.error?.message?.includes(
            'This feature is not enabled'
          ) && message.error('Multi factor authentication is not enabled for your organization.')
        
  }, [mfaData, loading])

  const renderDisableMfaContent = () => {
    if (continueDisableMfa) {
      return (
        <>
        <h2>Enter multi factor authentication code</h2>
        <p>MFA code is required to disable the multi-factor authentication.</p>

        <FormContainer ref={formRef} onFinish={handlePasswordVerification}>
          <FormItemStyled
            name="password"
            rules={[{ 
              required: true, 
              message: 'The code you entered is incorrect. Please try again.',
            }
          ]}
          >
            <Input
              suffix={
                showPassword ? (
                  <EyeOutlined onClick={() => setShowPassword(!showPassword)} color='#D0D2D7'/>
                ) : (
                  <EyeInvisibleOutlined onClick={() => setShowPassword(!showPassword)} color='#D0D2D7'/>
                )
              }
              name="UXCam-password"
              autoComplete="chrome-off"
              type={showPassword ? 'userName' : "password"}
            />
          </FormItemStyled>

          <div className="modal-footer">
            <Button onClick={() => {
              setContinueDisableMfa(false)
              setVisibleDisableMFAModal(false)
            }} type='link'>
              Cancel
            </Button>
            <Button type="primary" loading={isLoading} htmlType={'submit'}>
              Disable
            </Button>
          </div>
        </FormContainer>
        </>
      )
    } else {
      return (
        <>
        <h2>Disable multi-factor authentication</h2>
        <p>
          Are you sure you want to disable multi-factor authentication? You will
          have to go through the setup process to enable it again.
        </p>
        <div className="modal-footer">
          <Button onClick={() => setVisibleDisableMFAModal(false)} type='link'>
            Cancel
          </Button>
          <Button type="primary" loading={isLoading} onClick={() => setContinueDisableMfa(true)}>
            Continue
          </Button>
        </div>
        </>
      )
    }
  }

  return (
    <>
      <StyledMFAButton loading={loading} onClick={handleModalDisplay}>
        {isMfaEnabled
          ? 'Disable multi-factor authentication'
          : 'Enable multi-factor authentication'}
      </StyledMFAButton>
      {mfaData?.secret ? (
        <StyledEnableModal
          visible={!loading && visibleMfa}
          wrapClassName="mfa-modal-box"
          footer={null}
          closable={false}
          onCancel={() => flagChange(false)}
          destroyOnClose
          style={{ width: '490px' }}
        >
          <p className="title">Enable multi-factor authentication</p>
          <p>
            Add an extra layer of protection on top of your user name and
            password.
          </p>
          <ul>
            <li>
              <h4>Download an authenticator app</h4>
              <a
                href="https://apps.apple.com/us/app/google-authenticator/id388497605"
                target="_blank"
                rel="noreferrer"
              >
                Google Authenticator for iOS
              </a>
              <br />
              <a
                href="https://play.google.com/store/apps/details?id=com.google.android.apps.authenticator2"
                target="_blank"
                rel="noreferrer"
              >
                Google Authenticator for Android
              </a>
            </li>
            <li>
              <h4>Scan this QR code with your authenticator app</h4>
              <div style={{ display: 'flex', alignItems: 'center' }}>
                <StyledFigure>
                  <img
                    src={
                      mfaData
                        ? mfaData?.mfaQrUrl
                        : 'https://fakeimg.pl/150x150/'
                    }
                    alt=""
                  />
                </StyledFigure>
                <div style={{ marginLeft: '70px' }}>
                  <h4>Or Enter this secret key</h4>{' '}
                  <strong style={{ color: '#5D97FF', letterSpacing: '0.8px' }}>
                    {mfaData.secret}
                  </strong>
                </div>
              </div>
            </li>
            <li style={{ border: '0', margin: '0', padding: '0' }}>
              <h4>Enter two consecutive authentication codes</h4>
              <Form ref={formRef} onFinish={handleSubmit}>
                <FormItem
                  name="code1"
                  rules={[
                    {
                      required: true,
                      message: 'Please enter first authentication code',
                    },
                  ]}
                >
                  <Input placeholder="Enter first authentication code" />
                </FormItem>
                <FormItem
                  name="code2"
                  rules={[
                    {
                      required: true,
                      message: 'Please enter next authentication code',
                    },
                  ]}
                >
                  <Input placeholder="Enter next authentication code" />
                </FormItem>
                <FormItem className="modal-footer-part">
                  <StyledButton
                    onClick={() => flagChange()}
                    className="cancel-btn"
                  >
                    Cancel
                  </StyledButton>
                  <StyledButton
                    type="primary"
                    htmlType="submit"
                    loading={isLoading}
                  >
                    Enable
                  </StyledButton>
                </FormItem>
              </Form>
            </li>
          </ul>
        </StyledEnableModal>
      ) : (
        ''
      )}
      <StyledDisableModal
        visible={visibleDisableMFAModal}
        title=''
        footer={null}
        closable={false}
        onCancel={() => setVisibleDisableMFAModal(false)}
        wrapClassName="disable-modal-box"
        style={{ top: 270 }}
      >
        { renderDisableMfaContent() }
      </StyledDisableModal>
    </>
  );
};

export default MultiFactorAuthentication;
